#!/data/data/com.termux/files/usr/bin/bash
# OBSIDIANTI_MWNI_REVIEW_RECOVERY_v1.4.3
# Recover four SHA-proven Mwni review exports from previous Termux/proot run.
# Execution and publication authority: ANDROID TERMUX GIT ONLY.
set -euo pipefail
SELF="$(readlink -f "${BASH_SOURCE[0]}")"
PACKET_SHA256=2da9263783bbe327609b8e19c33883e44a0c55f0b41bfa384e61af3402c20663
if [[ "${1:-}" == '--selftest' ]]; then
  bash -n "$SELF"
  echo 'LAUNCHER_SYNTAX=PASS'
fi
for bin in python3 git sha256sum base64 tar; do
  if ! command -v "$bin" >/dev/null 2>&1; then echo "BLOCKED:MISSING_DEPENDENCY=$bin" >&2; exit 2; fi
done
TMP="$(mktemp -d "${TMPDIR:-/tmp}/obs-mwni-recovery-v143.XXXXXXXX")"
trap 'rm -rf "$TMP"' EXIT
ENTRY="$(awk '/^__EMBEDDED_PACKET__$/ {print NR+1;exit}' "$SELF")"
[[ -n "$ENTRY" ]] || { echo 'BLOCKED:PACKET_MARKER_MISSING' >&2;exit 3; }
tail -n +"$ENTRY" "$SELF" | base64 -d > "$TMP/packet.tar.gz"
printf '%s  %s\n' "$PACKET_SHA256" "$TMP/packet.tar.gz" | sha256sum -c -
mkdir -p "$TMP/packet"
tar -xzf "$TMP/packet.tar.gz" -C "$TMP/packet" --no-same-owner --no-same-permissions
python3 - "$TMP/packet" <<'PY_CHECK'
import hashlib,json,pathlib,sys
root=pathlib.Path(sys.argv[1]);d=json.loads((root/'manifest.json').read_text());expected={'driver.py','test_driver.py','contract.json'}
assert set(d)==expected,(d,expected)
for n,hash_ in d.items():assert hashlib.sha256((root/n).read_bytes()).hexdigest()==hash_,n
print('PACKET_INTEGRITY=PASS')
PY_CHECK
if [[ "${1:-}" == '--verify-packet' || "${1:-}" == '--selftest' ]]; then
  python3 "$TMP/packet/test_driver.py"
  echo 'PACKET_TESTS=PASS'
  exit 0
fi
printf 'CAMPAIGN=OBSIDIANTI_MWNI_REVIEW_RECOVERY_v1.4.3\n'
printf 'AUTHORITY=TERMUX_GIT_ONLY\n'
printf 'LAUNCHER_SHA256=%s\n' "$(sha256sum "$SELF" | cut -d' ' -f1)"
printf 'PACKET_SHA256=%s\n' "$PACKET_SHA256"
exec python3 "$TMP/packet/driver.py" "$TMP/packet" "$SELF" "$(sha256sum "$SELF" | cut -d' ' -f1)"
__EMBEDDED_PACKET__

